"""Mutalia-e-Quran XII PDF109: p.106 — Surah al-Ahzab heading; verses 33:1–5 (33:6 continues onto p.107; recorded there). Run: python class12_quran_page109.py"""
from class12_quran_common import BOOK, Builder, rec, V


def p109():
    b = Builder()
    b.h('Surah al-Ahzab (33) — Madani; order of revelation 90; verses 73, sections 9', 'سُوْرَةُ الْأَحْزَابِ ۳۳ — مَدَنِيَّةٌ ۹۰ — اٰیَاتُهَا ۷۳، رُکُوْعَاتُهَا ۹', 'سورة الاحزاب (۳۳) — مدني؛ د نزول ترتیب ۹۰؛ آیتونه ۷۳، رکوعونه ۹')
    b.p('بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ\nIn the name of Allah, the Beneficent, the Merciful.', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ\nاللہ کے نام سے شروع جو بڑا مہربان نہایت رحم فرمانے والا ہے', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ\nد الله په نوم پیل چې ډېر مهربان، بې‌حده رحم کوونکی دی')
    b.paras[-1]['arabicSource'] = True
    V(b, 33, 1, 'اے نبی (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم)! اللہ سے ڈرتے رہیں اور کافروں اور منافقوں کی بات (کبھی) نہ مانیں بے شک اللہ خوب جاننے والا بڑی حکمت والا ہے۔',
      'ای نبي (صلی الله علیه وعلی آله واصحابه وسلم)! له الله وېرېږئ او د کافرانو او منافقانو خبره (هېڅکله) مه منئ؛ بې‌شکه الله ښه پوه، ډېر حکمتناک دی.')
    V(b, 33, 2, 'اور جو کچھ آپ کے رب کی طرف سے آپ کی طرف وحی کیا جا رہا ہے اس کی پیروی کیجیے بے شک (اے لوگو!) اللہ اُس سے خوب باخبر ہے جو عمل تم کرتے ہو۔',
      'او ستاسو د رب له لوري چې څه تاسو ته وحې کېږي، د هغه پیروي وکړئ؛ بې‌شکه (ای خلکو!) الله په هغه عمل ښه خبر دی چې تاسو یې کوئ.')
    V(b, 33, 3, 'اور اللہ ہی پر بھروسہ رکھیے اور اللہ ہی کارساز کافی ہے۔',
      'او یوازې پر الله توکل وکړئ، او یوازې الله کارساز بس دی.')
    V(b, 33, 4, 'اللہ نے کسی آدمی کے لیے اُس کے سینے میں دو دل نہیں بنائے اور اس نے (ایمان والو!) تمھاری بیویوں کو جن سے تم ظہار کرتے ہو تمھاری (حقیقی) مائیں نہیں بنایا اور تمھارے منہ بولے بیٹوں کو تمھارے (حقیقی) بیٹے نہیں بنایا یہ سب تمھارے اپنے منہ کی باتیں ہیں اور اللہ حق بات فرماتا ہے اور وہی (سیدھا) راستہ دکھاتا ہے۔',
      'الله د هېڅ سړي لپاره په سینه کې دوه زړونه نه دي جوړ کړي، او (ای مؤمنانو!) هغه ستاسو هغه مېرمنې چې ورسره ظهار کوئ، ستاسو (حقیقي) میندې نه دي ګرځولې، او ستاسو خوله‌ویلي زامن یې ستاسو (حقیقي) زامن نه دي ګرځولي؛ دا ټول ستاسو د خپلې خولې خبرې دي؛ او الله حقه خبره کوي او همغه (سمه) لار ښيي.')
    V(b, 33, 5, 'تم ان (منہ بولے بیٹوں) کو ان کے باپ (کے ہی نام) سے پکارا کرو یہ (طریقہ) اللہ کے نزدیک پورے انصاف کی بات ہے پھر اگر تمھیں ان کے باپ معلوم نہ ہوں تو (وہ) تمھارے دینی بھائی ہیں اور تمھارے دوست ہیں اور اس بات میں تم پر کوئی گناہ نہیں ہے جو تم نے غلطی سے کہی لیکن (اُس پر گناہ ہوگا) جس کا ارادہ تمھارے دلوں نے جان بوجھ کر کیا ہو اور اللہ بڑا ہی بخشنے والا نہایت رحم فرمانے والا ہے۔',
      'تاسو هغوی (خوله‌ویلي زامن) د هغوی د پلرونو (په نوم) یاد کړئ؛ دا (طریقه) د الله په وړاندې پوره انصاف دی؛ بیا که د هغوی پلرونه درته معلوم نه وي، نو (هغوی) ستاسو دیني وروڼه او ستاسو دوستان دي؛ او په هغه خبره کې پر تاسو څه ګناه نشته چې په تېروتنه مو کړې وي، خو (ګناه به په هغه وي) چې ستاسو زړونو په قصد اراده کړې وي؛ او الله ډېر بښونکی، بې‌حده مهربان دی.')
    BOOK.save(109, [(11, rec(b, 11, 109, 109))], issues=[{'id': 'mq12-pdf109', 'unit': 11, 'printedPage': 106,
               'description': 'Surah heading cartouche: al-Ahzab 33, Madaniyyah 90, ayat 73, ruku 9. Verse 33:6 begins on p.106 (last two lines) and is recorded with p.107.'}])


if __name__ == '__main__':
    p109()
